import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"交付路线与实施计划","description":"Hearth 的六个交付阶段：从最小完整 MVP 到可长期运行的个人 Agent OS。","frontmatter":{"title":"交付路线与实施计划","description":"Hearth 的六个交付阶段：从最小完整 MVP 到可长期运行的个人 Agent OS。","outline":[2,3]},"headers":[],"relativePath":"delivery/index.md","filePath":"delivery/index.md","lastUpdated":1793867008000}'),h={name:"delivery/index.md"};function l(o,t,i,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="交付路线与实施计划" tabindex="-1">交付路线与实施计划 <a class="header-anchor" href="#交付路线与实施计划" aria-label="Permalink to &quot;交付路线与实施计划&quot;">​</a></h1><p class="lead">这份路线只回答两件事：先做什么，后做什么；每个阶段怎样从可用走到可靠。</p><h2 id="总体目标" tabindex="-1">总体目标 <a class="header-anchor" href="#总体目标" aria-label="Permalink to &quot;总体目标&quot;">​</a></h2><p>Hearth 的目标是把个人数字工作变成可靠的任务。路线不从架构模块出发，而从用户能完成的事情出发：先交付一个最小完整产品，再逐步扩大工作范围、主动性、记忆和多设备能力。</p><h2 id="六个阶段" tabindex="-1">六个阶段 <a class="header-anchor" href="#六个阶段" aria-label="Permalink to &quot;六个阶段&quot;">​</a></h2><p>每个阶段都包含四个小阶段，点击阶段名称可以进入详细计划。</p><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>完成后得到什么</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-1.html">第一阶段 · 最小完整 MVP</a></td><td>交付一个以 15 个跨行业真实任务为基线、至少通过 10 个的最小完整产品。</td><td>一个能每天使用、覆盖多个任务族的本地任务工作台</td></tr><tr><td><a href="/hearth-os/delivery/stage-2.html">第二阶段 · 日常内容工作</a></td><td>从首批跨行业任务扩展到邮件、日历、文档、表格和网页。</td><td>能处理日常内容并在审批后安全写入的个人操作员</td></tr><tr><td><a href="/hearth-os/delivery/stage-3.html">第三阶段 · 桌面操作</a></td><td>让 Hearth 操作没有开放接口的桌面软件和跨应用流程。</td><td>能操作桌面软件、可暂停、可接管、失败可恢复的助手</td></tr><tr><td><a href="/hearth-os/delivery/stage-4.html">第四阶段 · 主动服务与手机入口</a></td><td>在有限授权内主动工作，并把手机作为审批和接管入口。</td><td>能在合适时机提醒，并可在手机上审批和接管的助手</td></tr><tr><td><a href="/hearth-os/delivery/stage-5.html">第五阶段 · 记忆与能力进化</a></td><td>让系统积累背景并改进方法，但所有变化都可查看、可纠正、可回退。</td><td>会积累背景、改进方法且可纠正可回退的助手</td></tr><tr><td><a href="/hearth-os/delivery/stage-6.html">第六阶段 · 多设备与长期运行</a></td><td>让同一套任务、记忆和授权在多台设备上长期安全使用。</td><td>可多设备使用、可迁移、可长期运行的个人 Agent OS</td></tr></tbody></table><h2 id="怎么推进" tabindex="-1">怎么推进 <a class="header-anchor" href="#怎么推进" aria-label="Permalink to &quot;怎么推进&quot;">​</a></h2><ol><li><strong>先完整后扩展。</strong> 先把首批 15 个任务中的至少 10 个做完整，再增加新的信息来源、操作方式和设备。</li><li><strong>先只读后写入，先低风险后高风险。</strong> 每一类外部操作都先观察、再起草、再审批执行。</li><li><strong>每阶段都用真实任务验收。</strong> 不以代码写完或页面做完作为完成标准。</li><li><strong>安全和恢复从第一阶段就有。</strong> 审批、产物、失败恢复、权限边界不放到最后补。</li></ol><p>从<a href="/hearth-os/delivery/stage-1.html">第一阶段 · 最小完整 MVP</a>开始。</p>',10)])])}const m=e(h,[["render",l]]);export{_ as __pageData,m as default};
